package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.lianxibu.site.repository.jobs.*;import com.lianxibu.site.domain.jobs.BacklogHistoryTelemetry.Mutation;import java.time.*;import javax.sql.DataSource;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.*;import org.springframework.transaction.support.TransactionTemplate;
class SharedWriteMutationWitnessTest {
 static class Fixture{DataSource source;JdbcTemplate sql;DataSourceTransactionManager tx;SharedWriteExecutor writes;OperationalPersistenceFixture.MutableClock clock=new OperationalPersistenceFixture.MutableClock();Fixture(DataSource source){this.source=source;sql=new JdbcTemplate(source);tx=new DataSourceTransactionManager(source);writes=new SharedWriteExecutor(new JdbcSharedWriteEntry(source),tx,()->25,n->{});sql.execute("ALTER TABLE worker_lock ADD COLUMN fictional_marker INT NOT NULL DEFAULT 0");}}
 Fixture fixture(){return new Fixture(new OperationalPersistenceFixture().source);}
 Mutation read(Fixture f,JdbcBacklogMutationWitness.Scope scope){var rr=new TransactionTemplate(f.tx);rr.setReadOnly(true);rr.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);return rr.execute(s->scope.read());}
 void write(Fixture f,String key,String id){f.writes.execute(new SharedWriteExecutor.ActionContext(key,id,null),ignored->null,ignored->{f.sql.update("UPDATE worker_lock SET fictional_marker=fictional_marker+1");return true;});}
 @Test void unregisteredOriginalWritesAndRegistrationAreColdAndDefaultOff(){var f=fixture();write(f,"fictional-before","fictional-business");assertEquals(0,f.sql.queryForObject("SELECT COUNT(*) FROM runtime_settings WHERE setting_key=?",Integer.class,JdbcBacklogMutationWitness.KEY));var ds=mock(DataSource.class);var clock=mock(Clock.class);try(var scope=JdbcBacklogMutationWitness.open(ds,clock)){assertEquals("BacklogMutationScope[redacted]",scope.toString());verifyNoInteractions(ds,clock);}}
 @Test void nativeCommitCountsBusinessOnceAndClosedOriginalObservationKeysDoNotClaimMutation(){var f=fixture();try(var scope=JdbcBacklogMutationWitness.open(f.source,f.clock)){assertNull(read(f,scope));write(f,"fictional-business-1","fictional-business");assertEquals(1,read(f,scope).sequence());String hash="a".repeat(32);write(f,"api-sample:"+hash+":60","ops_"+hash);write(f,"collector-heartbeat:"+"b".repeat(64),"collector-heartbeat");assertEquals(1,read(f,scope).sequence());write(f,"api-sample:"+hash+":60","fictional-business");assertEquals(2,read(f,scope).sequence());assertEquals(4,f.sql.queryForObject("SELECT fictional_marker FROM worker_lock",Integer.class));}}
 @Test void failedOriginalWorkAndDamagedWitnessRollBackOriginalBusinessMarker(){var f=fixture();try(var scope=JdbcBacklogMutationWitness.open(f.source,f.clock)){assertThrows(IllegalStateException.class,()->f.writes.execute(new SharedWriteExecutor.ActionContext("fictional-fail","fictional-business",null),k->null,k->{f.sql.update("UPDATE worker_lock SET fictional_marker=1");throw new IllegalStateException("fictional rollback");}));assertNull(read(f,scope));assertEquals(0,f.sql.queryForObject("SELECT fictional_marker FROM worker_lock",Integer.class));write(f,"fictional-good","fictional-business");f.sql.update("UPDATE runtime_settings SET value_json='{}' WHERE setting_key=?",JdbcBacklogMutationWitness.KEY);assertThrows(RuntimeException.class,()->write(f,"fictional-damaged","fictional-business"));assertEquals(1,f.sql.queryForObject("SELECT fictional_marker FROM worker_lock",Integer.class));}}
 @Test void nativeReceiptReplayDoesNotRunBodyOrCountAnotherCommit(){var f=fixture();try(var scope=JdbcBacklogMutationWitness.open(f.source,f.clock)){var committed=new java.util.concurrent.atomic.AtomicReference<String>();var context=new SharedWriteExecutor.ActionContext("fictional-replay","fictional-business",null);String actual=f.writes.execute(context,k->committed.get(),k->{f.sql.update("UPDATE worker_lock SET fictional_marker=1");return "fictional result";});committed.set(actual);assertEquals(actual,f.writes.execute(context,k->committed.get(),k->{fail("native receipt already committed");return null;}));assertEquals(1,read(f,scope).sequence());assertEquals(1,f.sql.queryForObject("SELECT fictional_marker FROM worker_lock",Integer.class));}}
 @Test void registrationRestartChangesEpochAndOldHandleCannotDisableOrReadNewEpoch(){var f=fixture();String before;var old=JdbcBacklogMutationWitness.open(f.source,f.clock);write(f,"fictional-old","fictional-business");before=read(f,old).epoch();assertThrows(IllegalStateException.class,()->JdbcBacklogMutationWitness.open(f.source,f.clock));old.close();f.clock.now=f.clock.now.plusSeconds(60);try(var next=JdbcBacklogMutationWitness.open(f.source,f.clock)){assertNull(read(f,next));old.close();write(f,"fictional-new","fictional-business");assertNotEquals(before,read(f,next).epoch());assertEquals(1,read(f,next).sequence());assertThrows(IllegalStateException.class,()->read(f,old));}}
 @Test void rollbackUnsafeSequenceAndWrongReadRoleNeverProduceHealthyWitness(){var f=fixture();try(var scope=JdbcBacklogMutationWitness.open(f.source,f.clock)){assertThrows(IllegalStateException.class,scope::read);write(f,"fictional-one","fictional-business");f.clock.now=f.clock.now.minusSeconds(1);assertThrows(RuntimeException.class,()->write(f,"fictional-rollback","fictional-business"));assertEquals(1,f.sql.queryForObject("SELECT fictional_marker FROM worker_lock",Integer.class));f.clock.now=f.clock.now.plusSeconds(1);String raw=f.sql.queryForObject("SELECT value_json FROM runtime_settings WHERE setting_key=?",String.class,JdbcBacklogMutationWitness.KEY);var parsed=(tools.jackson.databind.node.ObjectNode)com.lianxibu.site.domain.protocol.CanonicalJson.parse(raw);parsed.put("sequence",9007199254740991L);raw=JdbcFrozenInputs.canonical(parsed);f.sql.update("UPDATE runtime_settings SET value_json=? WHERE setting_key=?",raw,JdbcBacklogMutationWitness.KEY);assertThrows(RuntimeException.class,()->write(f,"fictional-overflow","fictional-business"));assertEquals(1,f.sql.queryForObject("SELECT fictional_marker FROM worker_lock",Integer.class));}}
 @Test void firstPureMonitorWriteEstablishesNativeWitnessWithoutBusinessCount(){var f=fixture();try(var scope=JdbcBacklogMutationWitness.open(f.source,f.clock)){String hash="c".repeat(32);write(f,"source-sample:"+hash+":60","ops_"+hash);assertEquals(0,read(f,scope).sequence());assertEquals("BacklogMutationWitness[redacted]",read(f,scope).toString());}}
}
